// Set / Map 字面量、上下文类型、值复制与 Equal / 可选 Hash 键协议。
int64 evaluations = 0;
int64 equalCalls = 0;
int64 hashCalls = 0;
int64 step() { evaluations = evaluations + 1; return evaluations; }
struct HashedKey : Equal<bool, HashedKey>, Hash<HashedKey> {
    int64 id; String label;
    bool leftEqual(HashedKey value) { equalCalls = equalCalls + 1; return self.id == value.id; }
    uint64 hash(HashedKey value) { hashCalls = hashCalls + 1; return (uint64)(self.id % 2); }
};
struct PlainKey : Equal<bool, PlainKey> {
    int64 id;
    bool leftEqual(PlainKey value) { return self.id % 10 == value.id % 10; }
};
interface KeyProtocol : Equal<bool, DerivedKey>, Hash<DerivedKey> {};
struct DerivedKey : KeyProtocol {
    int64 id;
    bool leftEqual(DerivedKey value) { return self.id == value.id; }
    uint64 hash(DerivedKey value) { return (uint64)self.id; }
};
struct Holder { Map<HashedKey, String> values; };
HashedKey key(int64 id, String label) { HashedKey value; value.id = id; value.label = label; return value; }
Set<int64> makeSet() { return {1, 2, 2, 3}; }
Map<String, String> makeMap() { return {"first": "one", "second": "two"}; }
Map<String, int64> emptyMap() { return {}; }
int64 count(Set<int64> values) { return values.len(); }
int64 mapCount(Map<String, int64> values) { return values.len(); }
void main() {
    let set = {3, 1, 3, 2,};
    assert(set.len() == 3 && set.has(1) != 0 && set.has(2) != 0 && set.has(3) != 0);
    let map = {"a": 1, "b": 2, "a": 3,};
    assert(map.len() == 2 && map["a"] == 3 && map["b"] == 2);
    let ordered = {step(): step(), step(): step()};
    assert(evaluations == 4 && ordered[1] == 2 && ordered[3] == 4);
    List<int64> emptyList = [];
    List<int64> numbers = [3, 1, 3, 2];
    List<String> words = ["one", "two"];
    List<int64> fromEmpty = [];
    assert(emptyList.len() == 0 && fromEmpty.len() == 0);
    assert(numbers.len() == 4 && numbers[0] == 3 && numbers[3] == 2);
    assert(words.len() == 2 && words[1] == "two");
    numbers.push(9);
    assert(numbers.len() == 5 && numbers[4] == 9);
    Set<int64> emptySet = {};
    Map<String, int64> empty = {};
    assert(emptySet.len() == 0 && empty.len() == 0 && emptyMap().len() == 0);
    assert(count({}) == 0 && count({1, 2}) == 2 && mapCount({}) == 0);
    set = {}; map = {};
    assert(set.len() == 0 && map.len() == 0);
    Set<uint8> small = {1, 2, 3};
    Set<float64> real = {1, 2.5};
    let inferredReal = {1, 2.5};
    assert(small.len() == 3 && real.has(1.0) != 0 && inferredReal.has(2.5) != 0);
    let nested = {"filled": {1, 2}, "empty": {}};
    Map<String, Set<int64> > typedNested = {"empty": {}, "filled": {3, 4}};
    Set<int64> inner = nested["filled"];
    Set<int64> innerCopy = typedNested["filled"];
    inner.add(9);
    assert(inner.len() == 3 && innerCopy.len() == 2 && nested["empty"].len() == 0);
    Set<Set<int64> > sets;
    sets.add({});
    typedNested.put("another", {});
    assert(sets.len() == 1 && typedNested["another"].len() == 0);
    int64 before = evaluations;
    bool skipped = false && ({step(): step()}).len() > 0;
    assert(!skipped && evaluations == before);
    let tupleSet = {(1, "one"), (2, "two"), (1, "one")};
    assert(tupleSet.len() == 2);
    {
        int64 round = 0;
        while (round < 8) {

        let textSet = {"first", "sec" + "ond", "first"};
        let textMap = makeMap();
        Map<String, String> copied = textMap;
        textMap["first"] = "changed";
        assert(textSet.len() == 2 && copied["first"] == "one");
        assert(makeSet().len() == 3 && ({"x": "value"})["x"] == "value");
        let big = {1: BigInteger("12345678901234567890")};
        BigInteger number = big[1];
        assert(number == BigInteger("12345678901234567890"));
        let keyed = {key(1, "first"): "one", key(3, "collision"): "three", key(1, "duplicate"): "updated"};
        assert(keyed.len() == 2 && keyed[key(1, "query")] == "updated" && keyed[key(3, "query")] == "three");
        int64 position = 0;
        bool foundOriginal = false;
        while (position < keyed.len()) {
            HashedKey saved = keyed.keyAt(position);
            if (saved.id == 1) {
                assert(saved.label == "first");
                foundOriginal = true;
            }
            position = position + 1;
        }
        assert(foundOriginal);
        keyed.put(key(2, "even"), "two");
        equalCalls = 0; hashCalls = 0;
        assert(keyed.has(key(2, "query")) != 0 && equalCalls == 1 && hashCalls == 1);
        keyed[key(1, "replacement")] = "again";
        Map<HashedKey, String> copy = keyed;
        keyed.clear();
        assert(copy[key(1, "query")] == "again" && copy.remove(key(3, "query")) != 0 && copy.len() == 2);
        Holder holder;
        holder.values.put(key(4, "field"), "four");
        assert(holder.values[key(4, "query")] == "four");
        PlainKey first; first.id = 1; PlainKey duplicate; duplicate.id = 11;
        let plain = {first: "first", duplicate: "last"};
        assert(plain.len() == 1 && plain[first] == "last" && plain.has(duplicate) != 0);
        let plainCopy = plain.copy();
        assert(plainCopy.remove(duplicate) != 0 && plainCopy.len() == 0 && plain.len() == 1);
        DerivedKey inherited; inherited.id = 5;
        let derived = {inherited: 55};
        assert(derived[inherited] == 55);

            round = round + 1;
        }
    }
    // 花括号语句块及 loop / if 保持正常解析。
    {} { int64 local = 1; assert(local == 1); }
    if (true) {} else {}
    println("collection literals and key protocols OK");
}

/* map_get_option.chl —— `getOption` 给的是 `Option<V>`：键不在就拿到 `None`，不报错。
 *
 * 下标 `m[k]` 读不存在的键会**直接报运行期错误**（见错误样例 `map_missing_key`），
 * 所以"这个键可能没有、我想自己决定怎么办"的场合走 `getOption`：
 * 有就 `Value(v)`，没有就 `None`，由调用方分支处理。
 *
 *   ./chali samples/map_get_option.chl
 */
struct Box { int64 n; }

Option<int64> pick(Map<String,int64> const& m, String k)
{
    return m.getOption(k);
}

void main()
{
    Map<String, int64> ages;
    ages.put("amy", 11);
    ages.put("bob", 22);

    println("有 amy：{} 值={}",
    ages.getOption("amy").isValue(), ages.getOption("amy").unwrapOr(0));
    println("没有 zoe：isNone={} 兜底={}",
    ages.getOption("zoe").isNone(), ages.getOption("zoe").unwrapOr(-1));

    match (ages.getOption("bob")) {
        Option<int64>::Value(v) => { println("match 拿到 {}", v); }
        Option<int64>::None => { println("不该走到这里"); }
    }
    match (ages.getOption("zoe")) {
        Option<int64>::Value(v) => { println("不该拿到 {}", v); }
        Option<int64>::None => { println("match 走 None 分支"); }
    }

    /* 结构体当值、整数当键、字面量建的 map，问法都一样 */
    Map<String, Box> boxes;
    Box made;
    made.n = 42;
    boxes.put("b", made);
    println("结构体值：{}", boxes.getOption("b").unwrapOr(made).n);

    Map<int64, String> names = {7: "ada"};
    println("整数键：{} 有 9 吗={}",
    names.getOption(7).unwrapOr("-"), names.getOption(9).isValue());

    /* 把 map 传进函数再问，也照样能拿到 Option */
    println("形参：{}", pick(&ages, "amy").unwrapOr(0));
}

import std::iter;

void main() {
    Map<String, List<int64>> values = {"first": [1, 2], "second": [3]};
    Pair<String, List<int64>> converted = Pair<String, List<int64>>::create(("tuple", [4, 5]));
    let tuple = converted.toTuple();
    converted.second.clear();
    assert(tuple.0 == "tuple" && tuple.1.len() == 2);
    Pair<int64, String> scalar = Pair<int64, String>::create(7, "seven");
    assert(scalar.toTuple().0 == 7 && scalar.second == "seven");
    let inferred = Pair::create("inferred", (int64)9);
    let inferredTuple = Pair::create(((int64)3, "three"));
    assert(inferred.first == "inferred" && inferred.second == 9);
    assert(inferredTuple.toTuple().0 == 3 && inferredTuple.second == "three");
    int64 total = 0;
    int64 count = 0;
    for (Pair<String, List<int64>> entry in values.iter()) {
        assert(values.has(entry.first) != 0);
        total = total + entry.second.len();
        count = count + 1;
        entry.second.push(9);
    }
    assert(total == 3 && count == 2);
    assert(values["first"].len() == 2 && values["second"].len() == 1);
    List<Pair<String, List<int64>>> entries = values.intoIter().collect();
    assert(values.len() == 0 && entries.len() == 2);
    int64 sum = 0;
    for (let entry in entries) {
        sum = sum + entry.second.len();
    }
    assert(sum == 3);
    println("Map Pair iterator OK");
}

import std::algorithms;

struct Metric { float64 amount; };

Metric negateMetric(Metric item) {
    Metric result;
    result.amount = 0.0 - item.amount;
    return result;
}

void main() {
    List<Metric> measured;
    Metric source;
    source.amount = -2.5;
    measured.push(source);
    List<Metric> negated = std::algorithms::mapValue<Metric>(measured, negateMetric);
    Metric first = negated[0];
    println("{}", first.amount);
}

// 自定义 Set 元素必须使用 Equal，Hash 可选；冲突、复制、清空及默认字段均保留策略。
struct SetKey : Equal<bool, SetKey>, Hash<SetKey> {
    int64 id;
    String text;
    List<int64> data;
    bool leftEqual(SetKey other) { return self.id == other.id; }
    uint64 hash(SetKey other) { return (uint64)(self.id % 2); }
};
struct PlainSetKey : Equal<bool, PlainSetKey> {
    int64 id;
    String text;
    bool leftEqual(PlainSetKey other) { return self.id % 10 == other.id % 10; }
};
struct SetHolder { Set<SetKey> items; };
enum EnumSetKey : Equal<bool, EnumSetKey> {
    Empty, Item(int64 number, String text);
    int64 id() {
        match (self) {
            EnumSetKey::Empty => { return -1; }
            EnumSetKey::Item(number, text) => { return number; }
        }
        return -2;
    }
    bool leftEqual(EnumSetKey other) { return self.id() == other.id(); }
};
SetKey key(int64 id, String text) {
    SetKey result;
    result.id = id; result.text = text; result.data.push(id);
    return result;
}
void main() {
    {
        int64 i = 0;
        while (i < 8) {

        Set<SetKey> values = {key(1, "first"), key(3, "collision"), key(1, "different")};
        assert(values.len() == 2 && values.has(key(1, "lookup")) != 0);
        Set<SetKey> copy = values;
        values.clear();
        assert(copy.has(key(3, "after clear")) != 0);
        int64 position = 0;
        bool foundOriginal = false;
        while (position < copy.len()) {
            SetKey stored = copy.at(position);
            if (stored.id == 1) {
                assert(stored.text == "first" && stored.data[0] == 1);
                foundOriginal = true;
            }
            position = position + 1;
        }
        assert(foundOriginal);
        assert(copy.remove(key(1, "remove")) != 0 && copy.len() == 1);
        assert(copy.has(key(3, "remaining")) != 0);
        SetHolder holder;
        holder.items.add(key(5, "field"));
        assert(holder.items.has(key(5, "query")) != 0);
        PlainSetKey first; first.id = 1; first.text = "one";
        PlainSetKey duplicate; duplicate.id = 11; duplicate.text = "eleven";
        Set<PlainSetKey> plain = {first, duplicate};
        assert(plain.len() == 1 && plain.has(duplicate) != 0);
        Map<PlainSetKey, String> mapped = {first: "old", duplicate: "new"};
        assert(mapped.len() == 1 && mapped[first] == "new");
        Set<EnumSetKey> enums = {EnumSetKey::Item(1, "first"), EnumSetKey::Item(1, "duplicate"), EnumSetKey::Empty};
        assert(enums.len() == 2 && enums.has(EnumSetKey::Item(1, "query")) != 0);
        Set<EnumSetKey> enumCopy = enums;
        enums.clear();
        assert(enumCopy.has(EnumSetKey::Item(1, "copied")) != 0);

            i = i + 1;
        }
    }
    println("set key protocol OK");
}

struct DefaultBag { List<int64> values; Set<int64> keys; Map<int64,String> names; };
struct NestedDefaultBag { DefaultBag bag; };
DefaultBag globalBag;
NestedDefaultBag nested;
enum DefaultChoice { Empty, Values(List<int64> values); };
DefaultChoice globalChoice;
int64 resourceDrops=0;
struct GlobalResource : Drop {
    String text;
    void drop() { if(self.text!=""){resourceDrops++;} }
};
GlobalResource resource;
GlobalResource makeGlobalResource() { GlobalResource value; value.text="owned"; return value; }
struct NestedResource : Drop {
    int64 live; String text;
    void drop() { if(self.live==1){assert(self.text=="owned");} }
};
struct NestedResourceOwner { NestedResource value; };
NestedResourceOwner nestedResource;
NestedResourceOwner makeNestedResource() {
    NestedResourceOwner owner; owner.value.live=1; owner.value.text="owned"; return owner;
}
void main() {
    assert(globalBag.values.len()==0 && globalBag.keys.len()==0 && globalBag.names.len()==0);
    globalBag.values.push(7); globalBag.keys.add(8); globalBag.names.put(9,"name");
    assert(globalBag.values[0]==7 && globalBag.keys.has(8)!=0 && globalBag.names[9]=="name");
    nested.bag.values.push(10); assert(nested.bag.values[0]==10);
    {
        int64 i=0;
        while (i<10) {

        DefaultChoice empty;
        Result<List<int64>,List<int64>> result;
        result.unwrap().push(1);
        assert(result.unwrap().len()==0);

            i++;
        }
    }
    {
        int64 i=0;
        while (i<5) {
resource=makeGlobalResource();
            i++;
        }
    }
    assert(resourceDrops==4);
    resource.drop(); assert(resourceDrops==5);
    resource=makeGlobalResource(); assert(resourceDrops==5);
    nestedResource=makeNestedResource();
    nestedResource.drop();
    nestedResource=makeNestedResource();
    println("global container defaults OK");
}

import std::collections;

import std::memory;

import std::algorithms;

bool positive(int64 value) { return value > 0; }
int64 addValues(int64 left, int64 right) { return left + right; }

void main() {
    List<int64> values;
    values.push(4);
    values.push(1);
    values.push(3);
    List<int64> sorted = std::algorithms::sortValue<int64>(values);
    println("{} {} {} {} {}", sorted[0], sorted[1], sorted[2],
    std::algorithms::binarySearchValue<int64>(sorted, 3),
    std::algorithms::foldValue<int64>(sorted, 0, addValues));
    println("{} {} {}", values[0], values[1], values[2]);

    List<float64> stableValues;
    stableValues.push(-0.0);
    stableValues.push(2.0);
    stableValues.push(0.0);
    stableValues.push(1.0);
    List<float64> stableSorted = std::algorithms::sortValue<float64>(stableValues);
    println("{1:1F} {2:1F} {3:1F} {4:1F}", stableSorted[0], stableSorted[1],
    stableSorted[2], stableSorted[3]);
    println("{} {} {} {} {}", std::algorithms::findValue<int64>(sorted, 4),
    std::algorithms::minValue<int64>(9, 2), std::algorithms::maxValue<int64>(9, 2),
    std::algorithms::clampValue<int64>(12, 0, 10),
    std::algorithms::allValue<int64>(sorted, positive));
    println("{} {} {} {}", std::algorithms::minValue<int64>(9, 2, 7, -1),
    std::algorithms::maxValue<int64>(9, 2, 12, 7),
    std::algorithms::minValue<int64>(5), std::algorithms::maxValue<int64>(6));

    std::collections::Deque<int64> deque = std::collections::Deque<int64>::create();
    deque.pushBack(2);
    deque.pushFront(1);
    println("{} {} {}", deque.len(), deque.popFront().unwrap(),
    deque.popBack().unwrap());

    std::collections::Queue<int64> queue = std::collections::Queue<int64>::create();
    queue.push(7);
    queue.push(8);
    println("{} {}", queue.peek().unwrap(), queue.pop().unwrap());

    std::collections::RingBuffer<int64> ring = std::collections::RingBuffer<int64>::withCapacity(2);
    println("{} {} {}", ring.push(5), ring.push(6), ring.push(7));
    println("{} {}", ring.pop().unwrap(), ring.available());

    std::collections::FixedVector<int64> fixed = std::collections::FixedVector<int64>::withCapacity(1);
    println("{} {} {}", fixed.push(9), fixed.push(10), fixed[0]);

    int64 raw[] = new[2];
    raw[0] = 11;
    raw[1] = 12;
    std::memory::Span<int64> span = std::memory::Span<int64>::from(&raw[0], len(raw));
    println("{} {} {}", span.len(), span[0], span[1]);

    std::collections::Channel<int64> channel = std::collections::Channel<int64>::create();
    channel.send(21);
    println("{} {}", channel.len(), channel.receive().unwrap());

    Pair<int64, String> pair = Pair<int64, String>::create(7, "seven");
    println("{} {}", pair.first, pair.second);
    raw.drop();
}

import std::parse;
import std::io;

String describe<E: Error>(E error)
{
    return error.toString();
}

String describeInterface(Error const& error)
{
    return error.toString();
}

void main()
{
    MessageError message = MessageError::from("原始诊断");
    MessageError copy = message;
    copy.message = "独立副本";
    assert(describe(message) == "原始诊断");
    assert(describeInterface(&message) == "原始诊断");
    assert(copy.toString() == "独立副本");
    assert((std::parse::ParseError::Overflow).toString() != "");
    assert((std::io::IoError::Closed).toString() != "");
    Result<File, IoError> file = fileOpen("missing-error-protocol-file.chl", "r");
    assert(file.isErr());
    assert(file.error().toString().contains("fileOpen failed"));
    println("standard Error protocol OK");
}

/*
 * std_structured_data.chl —— `std::json` 与 `std::toml` 的读写样例。
 *
 * 本例将 find / keyAt / asString 的结果分别保存，方便逐层检查 Result/Option。
 * 当前语言也支持 root.find("x").unwrap() 等持资源结果的链式访问；编译器在完整
 * 表达式结束后清理中间值。节点拥有独立子树，close 不影响副本及已提取的子值。
 */
import std::json;
import std::toml;

void main() {
    Result<std::json::JsonValue, MessageError> parsed = std::json::parse(
    "{\"name\":\"中文\",\"items\":[1,2,3],\"active\":true,\"nothing\":null,"
    "\"ratio\":1.5,\"min\":-9223372036854775808}");
    std::json::JsonValue root = parsed.unwrap();
    assert(root.isObject() && root.len() == 6);
    Option<String> firstKey = root.keyAt(0);
    assert(firstKey.unwrap() == "name");
    Option<std::json::JsonValue> nameField = root.find("name");
    std::json::JsonValue nameValue = nameField.unwrap();
    Option<String> nameText = nameValue.asString();
    assert(nameText.unwrap() == "中文");

    Option<std::json::JsonValue> itemsField = root.find("items");
    std::json::JsonValue items = itemsField.unwrap();
    int64 sum = 0;
    for (std::json::JsonValue item in items) {
        Option<int64> itemNumber = item.asInt();
        sum = sum + itemNumber.unwrap();
    }
    assert(sum == 6 && items.at(-1).isNone() && items.at(3).isNone());
    Option<std::json::JsonValue> missingField = root.find("missing");
    assert(missingField.isNone());
    Option<std::json::JsonValue> activeField = root.find("active");
    std::json::JsonValue activeValue = activeField.unwrap();
    Option<bool> activeBool = activeValue.asBool();
    assert(activeBool.unwrap());
    Option<std::json::JsonValue> nothingField = root.find("nothing");
    std::json::JsonValue nothingValue = nothingField.unwrap();
    assert(nothingValue.isNull());
    Option<int64> nothingInt = nothingValue.asInt();
    assert(nothingInt.isNone());
    Option<std::json::JsonValue> ratioField = root.find("ratio");
    std::json::JsonValue ratioValue = ratioField.unwrap();
    Option<float64> ratioNumber = ratioValue.asFloat64();
    assert(ratioNumber.unwrap() == 1.5);
    Option<int64> ratioInt = ratioValue.asInt();
    assert(ratioInt.isNone());
    Option<std::json::JsonValue> minField = root.find("min");
    std::json::JsonValue minValue = minField.unwrap();
    Option<int64> minNumber = minValue.asInt();
    assert(format("{}", minNumber.unwrap()) == "-9223372036854775808");

    String rootText = root.dump();
    Result<std::json::JsonValue, MessageError> reparsed = std::json::parse(rootText);
    std::json::JsonValue reloaded = reparsed.unwrap();
    Option<std::json::JsonValue> reloadedName = reloaded.find("name");
    std::json::JsonValue reloadedNameValue = reloadedName.unwrap();
    Option<String> reloadedText = reloadedNameValue.asString();
    assert(reloadedText.unwrap() == "中文");
    assert(reloaded.close());
    assert(root.close() && items.isValid() && !root.close());

    Result<std::json::JsonValue, MessageError> parsedZero =
    std::json::parse("{\"a\\u0000b\":\"x\\u0000y\"}");
    std::json::JsonValue zero = parsedZero.unwrap();
    Option<String> zeroKey = zero.keyAt(0);
    assert(zeroKey.isNone());
    Option<List<uint8>> keyResult = zero.keyBytesAt(0);
    List<uint8> key = keyResult.unwrap();
    assert(key.len() == 3 && key[1] == (uint8)0);
    Option<std::json::JsonValue> zeroTextField = zero.findBytes(key);
    std::json::JsonValue zeroText = zeroTextField.unwrap();
    Option<String> zeroTextString = zeroText.asString();
    assert(zeroTextString.isNone());
    Option<List<uint8>> rawResult = zeroText.asBytes();
    List<uint8> raw = rawResult.unwrap();
    assert(raw.len() == 3 && raw[0] == (uint8)120 && raw[1] == (uint8)0 &&
    raw[2] == (uint8)121);
    assert(zero.close());
    Result<std::json::JsonValue, MessageError> badJson = std::json::parse("{\"x\":}");
    assert(badJson.isErr() && len(badJson.error().toString()) > 0);
    Result<std::json::JsonValue, MessageError> trailing = std::json::parse("[1,]");
    assert(trailing.isErr());

    Result<std::toml::TomlValue, MessageError> parsedConfig = std::toml::parse(
    "title = \"ChaLi\"\nreleased = 1979-05-27T07:32:00Z\n[server]\nport = 8080\n"
    "enabled = true\nvalues = [1, 2, 3]\n[[products]]\nname = \"one\"\n"
    "[[products]]\nname = \"two\"\n");
    std::toml::TomlValue config = parsedConfig.unwrap();
    assert(config.isTable());
    Option<String> titleKey = config.keyAt(0);
    assert(titleKey.unwrap() == "title");
    Option<std::toml::TomlValue> titleField = config.find("title");
    std::toml::TomlValue titleValue = titleField.unwrap();
    Option<String> titleText = titleValue.asString();
    assert(titleText.unwrap() == "ChaLi");
    Option<std::toml::TomlValue> serverField = config.find("server");
    std::toml::TomlValue server = serverField.unwrap();
    Option<std::toml::TomlValue> portField = server.find("port");
    std::toml::TomlValue portValue = portField.unwrap();
    Option<int64> portNumber = portValue.asInt();
    assert(portNumber.unwrap() == 8080);
