    {
        int64 i = 0;
        while (i < 50) {

        Result<std::json::JsonValue, MessageError> parsedSmall = std::json::parse("[]");
        std::json::JsonValue small = parsedSmall.unwrap();
        assert(small.close());
        Result<std::toml::TomlValue, MessageError> invalid = std::toml::parse("x = [");
        assert(invalid.isErr());

            i = i + 1;
