/* std_algorithms_extra.chl —— `algorithms` 的 map / filter / reduce / sum / count。
 *
 * 这一批和 `fold` / `all` / `any` 是同一套"回调式内建"：源码里写
 * `std::algorithms::mapValue<T>(表, 回调)`，泛型预处理器只负责吃掉 `<T>`，
 * 真正的降级在 `LowerAlgorithmCall`，运行期落到 VM 的 `__std_vec_map` 等等。
 *
 * 回调有两种写法，效果相同：
 *   ① 顶层函数名：`mapValue<int64>(values, doubled)`，按 `R fn(T)` 的函数值语义传入，
 *      写在 `module X;` 的文件里同样可用；
 *   ② 闭包：`mapValue<int64>(values, fn(int64 v) { v * 2 })`，可以捕获外层局部变量，
 *      生命周期与借用按函数值规则检查。
 */

import std::algorithms;

import std::text;

int64 doubled(int64 value) { return value * 2; }
float64 halved(int64 value) { return (float64)value / 2.0; }
String stars(int64 value) { return std::text::Text::repeat("*", value); }
int64 lengthOf(String text) { return len(text); }
bool odd(int64 value) { return value % 2 != 0; }
int64 addInt(int64 total, int64 value) { return total + value; }
float64 addReal(float64 total, float64 value) { return total + value; }

void main() {
    List<int64> values;
    values.push(3);
    values.push(1);
    values.push(4);
    values.push(1);
    values.push(5);

    /* map：结果表的元素类型由**回调的返回类型**定，`map<int64>` 只给一个类型实参。 */
    List<int64> tripled = std::algorithms::mapValue<int64>(values, doubled);
    List<float64> halves = std::algorithms::mapValue<int64>(values, halved);
    List<String> marks = std::algorithms::mapValue<int64>(values, stars);
    List<int64> lengths = std::algorithms::mapValue<String>(marks, lengthOf);

    /* filter：留下判定为真的元素，元素类型不变。 */
    List<int64> odds = std::algorithms::filterValue<int64>(values, odd);

    println("map    {} {} {}", tripled.len(), tripled[0], tripled[4]);
    println("map    {} {} {}", halves[0], marks[2], lengths[4]);
    println("filter {} {} {}", odds.len(), odds[0], odds[3]);

    /* reduce 两种写法：两参拿第一个元素当初值，三参等同 fold。 */
    println("reduce {} {}", std::algorithms::reduceValue<int64>(values, addInt),
    std::algorithms::reduceValue<int64>(values, 100, addInt));
    /* sum / count：count 的第二参是回调（函数值）就按判定数，是值就按相等数统计。 */
    println("sum    {} {}", std::algorithms::sumValue<int64>(values),
    std::algorithms::sumValue<float64>(halves));
    println("count  {} {}", std::algorithms::countValue<int64>(values, 1),
    std::algorithms::countValue<int64>(values, odd));

    /* 回调也可以是闭包：捕获外层局部变量，借用与生命周期按函数值规则检查。 */
    int64 offset = 10;
    List<int64> shifted = std::algorithms::mapValue<int64>(values, fn(int64 value) { value + offset });
    println("closure {} {}", shifted[0], shifted[4]);

    List<float64> reals;
    reals.push(1.5);
    reals.push(2.25);
    println("float64    {}", std::algorithms::reduceValue<float64>(reals, addReal));
}

/* 后置类型参数、函数实参推导、泛型回调及无载荷枚举上下文。 */
enum Choice<T> { None1, Value1(T value); };
struct Box<T> { T value; };


struct Handler {
    int64 take(Choice<int64> value) { return tag(value); }
};

T identity<T>(T value) { return value; }
T apply<T>(T fn(T) callback, T value) { return callback(value); }
T readBox<T>(Box<T> box) { return box.value; }
T first<T>(List<T> values) { return values[0]; }
T fromChoice<T>(Choice<T> value, T fallback) {
    match (value) {
        None1 => { return fallback; }
        Value1(item) => { return item; }
    }
    return fallback;
}
T fromCallback<T>(T fn(T) callback) { return callback((T)5); }
T readReference<T>(T const& value) { return value; }
T withDefault<T = int64>() { return (T)12; }
int64 increment(int64 value) { return value + 1; }
Choice<String> emptyText() { return None1; }
int64 tag(Choice<int64> value) {
    match (value) {
        None1 => { return 0; }
        Value1(item) => { return item; }
    }
    return -1;
}
void main() {
    int64 generic = 7;
    Box<int64> box;
    box.value = identity(generic);
    int64 fn(int64) callback = increment;
    Choice<int64> absent = None1;
    Choice<String> text = None1;
    Choice<int64> present = Value1(identity(42));
    absent = Value1(3);
    absent = None1;
    text = emptyText();
    let payload = Value1("text");
    println("{} {} {} {} {}", identity(8), apply(callback, 9), readBox(box), tag(present), tag(None1));
    match (payload) {
        None1 => { println("empty"); }
        Value1(item) => { println("{}", item); }
    }
    List<int64> values;
    values.push(11);
    println("{} {} {} {} {}", first(values), fromChoice(None1, 13), fromCallback(callback), readReference(&generic), withDefault());
    Handler handler;
    int64 fn(Choice<int64>) consumer = tag;
    println("{} {} {}", handler.take(None1), consumer(None1), identity("hello"));
    if (identity(2.5) != 2.5) { return; }
    let copiedCallback = identity(callback);
    let copiedFunction = identity(increment);
    println("{} {}", copiedCallback(20), copiedFunction(30));
}

/* generic_qualified.chl —— 模块里的泛型与静态成员：**裸名与限定名两种写法都要认**。
 *
 * 实例化体是按**裸名**登记的（`Box<int64>` → `Box__int`、`Point::origin`），所以
 * `custom::Box<int64>` / `custom::Point::origin` 这类限定写法必须在查找时去掉模块前缀。
 * 这条路径曾经静默失配：类型侧靠 FindStruct 兜底能"找到"，但候选签名按写出名去查
 * `g_funcs` 落空，报出来的却是"候选非空但参数类型对不上"，很难定位。
 */

module custom;

struct Box<T> {
    T value;

    static Box<T> of(T input) {
        Box<T> result;
        result.value = input;
        return result;
    }

    T get() {
        return self.value;
    }

    void set(T input) {
        self.value = input;
    }
};

struct Point {
    static int64 origin;
    int64 x;
};

void main() {
    Box<int64> plain = Box<int64>::of(1);                    /* 裸名 + 静态方法 */
    custom::Box<int64> qualified = custom::Box<int64>::of(2); /* 限定名 + 静态方法 */
    custom::Box<int64>::of(28).set(9);                     /* 限定名调用实例方法 */

    Box<float64> real = Box<float64>::of(2.5);                   /* 第二个实例化：签名必须换成 float64 */
    Box<char> letter = Box<char>::of('A');               /* 第三个实例化：char */

    Point point;
    point.x = 3;
    Point::origin = 5;                                   /* 裸名写静态字段 */
    custom::Point::origin = custom::Point::origin + 2;   /* 限定名读 + 写 */

    println("{} {} {} {}", plain.value, qualified.get(), real.value, letter.value);
    println("{} {} {}", point.x, Point::origin, custom::Point::origin);
}

interface RootValue { int64 value(); };
interface DerivedValue : RootValue { };
struct Number : DerivedValue { int64 value() { return 7; } };
int64 readValue<T: RootValue>(T item) { return item.value(); }
void main() { Number n; assert(readValue(n) == 7); println("inherited constraint OK"); }

interface Container { type Item; Item get(int64 index); Item first(){return self.get(0);} };
interface Derived : Container { };
struct Numbers : Derived { type Item=int64; Item get(int64 index){return index+11;} };
struct Words : Container { type Item=String; Item get(int64 index){return "word";} };
C.Item first<C:Container>(C value){return value.get(0);}
C.Item second<C:Container>(C value){C.Item item=value.get(1);return item;}
void main(){Numbers values;Words words;int64 n=first<Numbers>(values);String s=first<Words>(words);
    assert(n==11);assert(s=="word");assert(second<Numbers>(values)==12);assert(values.first()==11);
    println("associated ok");}

/* fn 与函数指针、惰性适配器、引用元素及拥有型返回值组合。 */
import std::iter;
import std::algorithms;


int64 apply(int64 fn(int64) callback, int64 value) { return callback(value); }
int64 applyAlias(int64 fn(int64) callback, int64 value) { return callback(value); }
T applyGeneric<T>(T fn(T) callback, T value) { return callback(value); }
void action(void fn() callback) { callback(); }
int64 observed = 0;

void main() {
    assert((apply(fn(value) { value + 3 }, 7)) == (10));
    assert((applyAlias(fn(value) { value * 2 }, 7)) == (14));
    assert((applyGeneric(fn(value) { value + 2 }, 7)) == (9));
    int64 fn(int64) increment = fn(value) { value + 1 };
    assert((increment(8)) == (9));
    let typed = fn(int64 value) { value * 3 };
    assert((apply(typed, 4)) == (12));
    List<int64> eager; eager.push(2); eager.push(3);
    let mapped = std::algorithms::mapValue<int64>(eager, fn(int64 value) { value * 2 });
    assert((mapped[1]) == (6));
    let selected = std::iter::range(1, 6)
    .map(fn(value) { value * 2 })
    .filter(bool fn(int64 value) { value > 4 })
    .inspect(void fn(int64 value) {})
    .collect();
    assert((selected.len()) == (3));
    assert((selected[0]) == (6));
    assert((selected[2]) == (10));
    let localWork = int64 fn(int64 seed) {
        let (a,b) = (seed,2);
        match(Option<int64>::Value(a)) {
            Option<int64>::Value(selected) => { return selected+b; }
            Option<int64>::None => { return 0; }
        }
        return 0;
    };
    assert((localWork(5)) == (7));
    assert((std::iter::range(1, 3).zip(std::iter::range(4, 6))
    .map(fn(pair) { pair.0 + pair.1 }).fold(0, fn(a,b) { a+b })) == (12));
    assert((std::iter::range(1, 5).fold(0, fn(acc, value) { acc + value })) == (10));
    assert((std::iter::range(1, 5).all(fn(value) { value > 0 })) == (true));
    assert((std::iter::range(1, 5).any(fn(value) { value == 3 })) == (true));
    assert((std::iter::range(1, 5).find(fn(value) { value == 2 }).unwrap()) == (2));
    assert((std::iter::range(1, 5).filterMap(Option<int64> fn(int64 value) {
        if (value % 2 == 0) { return Option<int64>::Value(value * 2); }
        return Option<int64>::None;
    }).count()) == (2));
    let scanned = std::iter::range(1, 4).scan(0, Option<int64> fn(int64 mut& acc, int64 value) {
        acc = acc + value;
        return Option<int64>::Value(acc);
    }).collect();
    assert((scanned[2]) == (6));
    assert((std::iter::range(1, 5).takeWhile(fn(value) { value < 3 }).count()) == (2));
    assert((std::iter::range(1, 5).skipWhile(fn(value) { value < 3 }).next().unwrap()) == (3));
    assert((std::iter::range(1, 5).mapWhile(Option<int64> fn(int64 value) {
        if (value < 3) { return Option<int64>::Value(value); }
        return Option<int64>::None;
    }).count()) == (2));
    assert((std::iter::range(1, 5).findMap(Option<int64> fn(int64 value) {
        if (value == 3) { return Option<int64>::Value(value * 2); }
        return Option<int64>::None;
    }).unwrap()) == (6));
    let checked = std::iter::range(1, 4).tryFold(0, Result<int64,String> fn(int64 acc,int64 value) {
        return Result<int64,String>::Ok(acc+value);
    });
    assert((checked.unwrap()) == (6));
    let split = std::iter::range(1, 5).peekingTakeWhile(fn(value) { value < 3 });
    let prefix = split.0;
    let rest = split.1;
    assert((prefix.count()) == (2));
    assert((rest.next().unwrap()) == (3));
    List<int64> numbers; numbers.push(1); numbers.push(2);
    {
        let refs = numbers.iterMut();
        refs.forEach(void fn(int64 mut& value) { value = value + 10; });
        assert((numbers[0]) == (11));
        assert((numbers.iter().map(fn(value) { value * 2 }).fold(0, fn(a,b) { a+b })) == (46));
    }
    {
        int64 round = 0;
        while (round < 4) {

        let labels = std::iter::range(1, 4).map(fn(value) { format("n{};", value) }).collect();
        assert((labels[2]) == ("n3;"));

            round = round + 1;
        }
    }
    let punctuation = fn() { "a;b" };
    assert((punctuation()) == ("a;b"));
    action(void fn() {});
    action(void fn() { assert(true) });
    action(void fn() { assert(true); return; });
    std::iter::range(1, 4).forEach(void fn(int64 value) { observed = observed + value; });
    assert((observed) == (6));
    observed = 10;
    let readGlobal = fn() { observed };
    observed = 20;
    assert((readGlobal()) == (20));
    println("fn callbacks OK");
}

/* 引用、独立副本和移动捕获的所有权与状态回归。 */
int64 drops=0;
int64 apply(int64 fn(int64) f,int64 x){return f(x);}
struct Record:Drop { String text; List<int64> values; void drop(){drops+=1;} };
int64 fn() counter(){int64 n=4;return int64 fn copy(){n+=1;return n;};}
int64 fn() movedCounter(){int64 n=8;return int64 fn move(){n+=1;return n;};}
void main(){
    int64 n=1;
    let read=int64 fn(){n};
    let explicitRead=int64 fn const(){n};
    n=2;assert(read()==2 && explicitRead()==2);
    let write=int64 fn mut(int64 x){n+=x;return n;};
    assert(write(3)==5 && n==5);
    let independent=int64 fn copy(int64 x){n+=x;return n;};
    n=100;assert(independent(2)==7 && independent(1)==8 && n==100);
    let cloned=independent;
    assert(cloned(3)==11 && independent(1)==9 && cloned(1)==12);
    const int64 fixed=7;
    let changeConst=int64 fn copy(){fixed+=1;return fixed;};
    assert(changeConst()==8 && fixed==7);
    let fromReturn=counter();assert(fromReturn()==5 && fromReturn()==6);
    let fromMove=movedCounter();assert(fromMove()==9 && fromMove()==10);
    String text="old";
    let copyText=String fn copy(){text=text+"!";return text;};
    text="outside";assert(copyText()=="old!" && copyText()=="old!!" && text=="outside");
    let copyText2=copyText;assert(copyText2()=="old!!!" && copyText()=="old!!!");
    List<int64> values;values.push(4);
    let copyList=int64 fn copy(){values[0]+=1;return values[0];};
    assert(copyList()==5 && copyList()==6 && values[0]==4);
    let copyList2=copyList;assert(copyList2()==7 && copyList2()==8 && copyList()==7);
    String moved="payload";int64 identity=0;memcpy(&identity,&moved,8);
    let takeText=int64 fn move(){int64 actual=0;memcpy(&actual,&moved,8);return actual;};
    assert(takeText()==identity);
    String moved="reset";assert(moved=="reset");
    List<int64> transferred;transferred.push(40);
    let takeList=int64 fn move(){transferred[0]+=1;return transferred[0];};
    List<int64> transferred;transferred.push(2);
    assert(takeList()==41 && takeList()==42 && transferred[0]==2);
    {Record record;record.text="owned";record.values.push(1);
        {let own=int64 fn copy(){record.values[0]+=1;return record.values[0];};
            assert(own()==2);{let second=own;assert(second()==3);}assert(drops==1);}
        assert(drops==2 && record.values[0]==1);}
    assert(drops==3);
    {Record record;record.text="moved";record.values.push(10);
        {let own=int64 fn move(){record.values[0]+=1;return record.values[0];};
            assert(own()==11 && drops==3);}
        assert(drops==4);}
    assert(drops==4);
    int64 referenced=20;int64 mut& alias=&referenced;
    let privateRef=int64 fn copy[alias](){alias+=1;return alias;};
    assert(privateRef()==21 && referenced==21);
    int64 mut& movedAlias=&referenced;
    let ownRef=int64 fn move[movedAlias](){movedAlias+=1;return movedAlias;};
    int64 mut& movedAlias=&referenced;assert(ownRef()==22 && movedAlias==22);
    float64 real=1.5;let realState=float64 fn copy(){real+=0.5;return real;};
    assert(realState()==2.0 && realState()==2.5 && real==1.5);
    int64 a=2;int64 b=3;int64 c=4;int64 d=5;
    let mixed=int64 fn copy[a] mut[b] const[c] move[d](int64 x){a+=x;b+=x;d+=x;return a+b+c+d;};
    a=100;c=10;int64 d=200;
    assert(mixed(1)==23 && a==100 && b==4 && c==10 && d==200);
    assert(mixed(1)==26 && b==5);
    let mixedCopy=mixed;
    assert(mixedCopy(1)==29 && b==6);
    assert(mixed(1)==30 && b==7);
    int64 bias=9;
    assert(apply(fn copy[bias](x){bias+=x;return bias;},2)==11 && bias==9);
    let empty=int64 fn copy[](){bias};bias=10;assert(empty()==10);
    int64 unused=7;let ignores=int64 fn move[unused](){1};
    int64 unused=8;assert(ignores()==1 && unused==8);
    int64 left=1;int64 right=2;int64 shared=3;
    let fallback=int64 fn copy[left,right] mut(int64 x){left+=x;right+=x;shared+=x;return left+right+shared;};
    assert(fallback(1)==9 && left==1 && right==2 && shared==4);
    assert(apply(fn copy[left,right] mut(x){shared+=x;return left+right+shared;},2)==9 && shared==6);
    int64 nestedSource=6;
    let outer=int64 fn copy(){let inner=int64 fn move[nestedSource](){1};return inner();};
    assert(outer()==1 && nestedSource==6);
    {Record record;
        {let unusedCopy=int64 fn copy[record](){1};
            {let neverCalled=unusedCopy;}
            assert(drops==5);
        }
        assert(drops==6);
    }
    assert(drops==7);
    println("fn capture modes OK");
}

