/* nested_result.chl —— 多层嵌套 Result：把"每一层各自失败"建模成一个值
 *
 *   ./chali samples/nested_result.chl
 *
 * 一条"取回文本 → 解析整数 → 语义校验"的流水线，每层有独立的错误枚举。三层 Result
 * 嵌套成一个对象（Ok 的载荷又是 Result）：
 *
 *   Result< Result< Result<int64, SemanticError>, SyntaxError >, TransportError >
 *   └ 外层 Err：传输失败    └ 中层 Err：解析失败    └ 内层 Err：校验失败
 *
 * 好处是调用者按层 match 就能拿到该层**具体**的错误类型和载荷，不必把三类错误
 * 压成一个扁平枚举。要汇成一句话，就在边界逐层拆（见 `report`）。
 *
 * `?` 只把**同一错误类型**往上送：跨层错误类型不同（TransportError / SyntaxError /
 * SemanticError），每过一层都要 match 后显式重包；这里只演示同一层内的 `?`
 * （见 `requireText`）。
 */

import std::parse;

enum TransportError {
    Offline(String endpoint),
    Timeout(String endpoint)
};

enum SyntaxError {
    EmptyField(String field),
    NotANumber(String field, String text)
};

enum SemanticError {
    Negative(String field, int64 value),
    TooLarge(String field, int64 value)
};

String describeTransport(TransportError error) {
    String result;
    match (error) {
        TransportError::Offline(endpoint) => { result = "offline(" + endpoint + ")"; }
        TransportError::Timeout(endpoint) => { result = "timeout(" + endpoint + ")"; }
    }
    return result;
}

String describeSyntax(SyntaxError error) {
    String result;
    match (error) {
        SyntaxError::EmptyField(field) => { result = "empty(" + field + ")"; }
        SyntaxError::NotANumber(field, text) => {
            result = "not-a-number(" + field + "=" + text + ")";
        }
    }
    return result;
}

String describeSemantic(SemanticError error) {
    String result;
    match (error) {
        SemanticError::Negative(field, value) => {
            result = "negative(" + field + "=" + format("{}", value) + ")";
        }
        SemanticError::TooLarge(field, value) => {
            result = "too-large(" + field + "=" + format("{}", value) + ")";
        }
    }
    return result;
}

/* 第 1 层：取回原始文本；失败给 TransportError。 */
Result<String, TransportError> fetch(String endpoint, bool online, String text) {
    if (!online) {
        return Result<String, TransportError>::Err(TransportError::Offline(endpoint));
    }
    if (endpoint == "slow") {
        return Result<String, TransportError>::Err(TransportError::Timeout(endpoint));
    }
    return Result<String, TransportError>::Ok(text);
}

/* 第 2 层：把文本解析成整数；失败给 SyntaxError。 */
Result<int64, SyntaxError> parse(String field, String text) {
    if (text == "") {
        return Result<int64, SyntaxError>::Err(SyntaxError::EmptyField(field));
    }
    Result<int64, std::parse::ParseError> parsed = std::parse::Parse::parseInt64(text);
    Result<int64, SyntaxError> result;
    match (parsed) {
        Result<int64, std::parse::ParseError>::Ok(value) => {
            result = Result<int64, SyntaxError>::Ok(value);
        }
        Result<int64, std::parse::ParseError>::Err(error) => {
            result = Result<int64, SyntaxError>::Err(SyntaxError::NotANumber(field, text));
        }
    }
    return result;
}

/* 第 3 层：数值语义校验；失败给 SemanticError。 */
Result<int64, SemanticError> validate(String field, int64 value) {
    if (value < 0) {
        return Result<int64, SemanticError>::Err(SemanticError::Negative(field, value));
    }
    if (value > 1000) {
        return Result<int64, SemanticError>::Err(SemanticError::TooLarge(field, value));
    }
    return Result<int64, SemanticError>::Ok(value);
}

/* 四个小包装，免得每处都把长类型抄一遍。 */
Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>
badTransport(TransportError error) {
    return Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>::Err(error);
}

Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>
badSyntax(SyntaxError error) {
    return Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>::Ok(
    Result<Result<int64, SemanticError>, SyntaxError>::Err(error));
}

Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>
badSemantic(SemanticError error) {
    return Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>::Ok(
    Result<Result<int64, SemanticError>, SyntaxError>::Ok(
    Result<int64, SemanticError>::Err(error)));
}

Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>
goodValue(int64 value) {
    return Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>::Ok(
    Result<Result<int64, SemanticError>, SyntaxError>::Ok(
    Result<int64, SemanticError>::Ok(value)));
}

/* 三层装载：Ok(Ok(Ok(v))) 全成功；哪层失败就把该层的 Err 放进对应槽。 */
Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>
loadField(String field, String endpoint, bool online, String text) {
    Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError> result;
    Result<String, TransportError> raw = fetch(endpoint, online, text);
    match (raw) {
        Result<String, TransportError>::Err(transportError) => {
            result = badTransport(transportError);
        }
        Result<String, TransportError>::Ok(value) => {
            Result<int64, SyntaxError> syntax = parse(field, value);
            match (syntax) {
                Result<int64, SyntaxError>::Err(syntaxError) => {
                    result = badSyntax(syntaxError);
                }
                Result<int64, SyntaxError>::Ok(parsed) => {
                    Result<int64, SemanticError> semantic = validate(field, parsed);
                    match (semantic) {
                        Result<int64, SemanticError>::Err(semanticError) => {
                            result = badSemantic(semanticError);
                        }
                        Result<int64, SemanticError>::Ok(number) => {
                            result = goodValue(number);
                        }
                    }
                }
            }
        }
    }
    return result;
}

/* 逐层拆开这个嵌套对象并汇报（不把它再塞进一个 Result<String>，见下）。 */
void report(String label,
Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError> nested) {
    match (nested) {
        Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>::Err(error) => {
            println("{} -> err transport:{}", label, describeTransport(error));
        }
        Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>::Ok(syntax) => {
            match (syntax) {
                Result<Result<int64, SemanticError>, SyntaxError>::Err(error) => {
                    println("{} -> err syntax:{}", label, describeSyntax(error));
                }
                Result<Result<int64, SemanticError>, SyntaxError>::Ok(semantic) => {
                    match (semantic) {
                        Result<int64, SemanticError>::Err(error) => {
                            println("{} -> err semantic:{}", label,
                            describeSemantic(error));
                        }
                        Result<int64, SemanticError>::Ok(value) => {
                            println("{} -> ok {}", label, value);
                        }
                    }
                }
            }
        }
    }
}

/* 同一错误类型的单层里 `?` 可以直接把 Err 送上去（这里返回类型也是 TransportError）。 */
Result<String, TransportError> requireText(String endpoint, bool online, String text) {
    String value = fetch(endpoint, online, text)?;
    return Result<String, TransportError>::Ok(value);
}

void main() {
    report("ok", loadField("count", "fast", true, "42"));
    report("empty", loadField("count", "fast", true, ""));
    report("text", loadField("count", "fast", true, "abc"));
    report("negative", loadField("count", "fast", true, "-7"));
    report("huge", loadField("count", "fast", true, "999999"));
    report("offline", loadField("count", "api", false, "42"));
    report("timeout", loadField("count", "slow", true, "42"));

    /* 也可以自己逐层拆：外层 -> 中层 -> 内层。 */
    Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError> nested =
    loadField("count", "fast", true, "7");
    match (nested) {
        Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>::Err(error) => {
            println("layer1 err {}", describeTransport(error));
        }
        Result<Result<Result<int64, SemanticError>, SyntaxError>, TransportError>::Ok(syntax) => {
            match (syntax) {
                Result<Result<int64, SemanticError>, SyntaxError>::Err(error) => {
                    println("layer2 err {}", describeSyntax(error));
                }
                Result<Result<int64, SemanticError>, SyntaxError>::Ok(semantic) => {
                    match (semantic) {
                        Result<int64, SemanticError>::Err(error) => {
                            println("layer3 err {}", describeSemantic(error));
                        }
                        Result<int64, SemanticError>::Ok(value) => {
                            println("layer3 ok {}", value);
                        }
                    }
                }
            }
        }
    }

    match (requireText("fast", true, "hello")) {
        Result<String, TransportError>::Ok(value) => { println("require ok {}", value); }
        Result<String, TransportError>::Err(error) => {
            println("require err {}", describeTransport(error));
        }
    }
    match (requireText("api", false, "hello")) {
        Result<String, TransportError>::Ok(value) => { println("require ok {}", value); }
        Result<String, TransportError>::Err(error) => {
            println("require err {}", describeTransport(error));
        }
    }
}

// 枚举的 List 载荷复制进 List/Map 后仍保持独立值语义。
enum Tree {
    Number(int64 value),
    Branch(String label, List<Tree> children);
};

Tree branch(String label, Tree left, Tree right) {
    List<Tree> children;
    children.push(left);
    children.push(right);
    return Tree::Branch(label, children);
}

int64 sum(Tree value) {
    match (value) {
        Tree::Number(number) => { return number; }
        Tree::Branch(label, children) => {
            int64 total = 0;
            {
                int64 i = 0;
                while (i < children.len()) {

                total = total + sum(children[i]);
                assert(label == "root" || label == "child");

                    i = i + 1;
                }
            }
            return total;
        }
    }
    return -1;
}

void main() {
    {
        int64 repeat = 0;
        while (repeat < 8) {

        Tree child = branch("child", Tree::Number(2), Tree::Number(3));
        Tree root = branch("root", Tree::Number(1), child);
        List<Tree> values;
        values.push(root);
        values.push(child);
        List<Tree> copied = values;
        Map<String, Tree> keyed;
        keyed.put("tree", root);
        Map<String, Tree> mapCopy = keyed;
        root = Tree::Number(100);
        child = Tree::Number(200);
        assert(sum(values[0]) == 6 && sum(values[1]) == 5);
        assert(sum(keyed["tree"]) == 6);
        values.clear();
        keyed.put("tree", Tree::Number(7));
        assert(sum(copied[0]) == 6 && sum(mapCopy["tree"]) == 6);
        assert(sum(keyed["tree"]) == 7);
        keyed.remove("tree");

            repeat = repeat + 1;
        }
    }
    println("nested enum ownership OK");
}

/* aggregate_ownership.chl —— 聚合槽里的字符串 / 对象归聚合自己所有。
 *
 *   ./chali samples/aggregate_ownership.chl
 *
 * 结构体、枚举（`Result` / `Option`）和元组都按值保存它们的槽：构造 / 复制进槽时
 * 字符串各复制一份，聚合销毁（出块 / return / 重新赋值 / drop / 停机）时按叶子
 * 递归释放。这里把几条最容易出问题的路径串起来，输出固定下来当回归：
 *
 *   * 构造器实参是"当场造出来的"字符串（`Ok(prefix + name)`），临时值也有主；
 *   * `?` 取出的字符串载荷，源 Result 释放后仍然有效；
 *   * `match` 绑定读字符串，分支里用没问题；
 *   * 元组变量、聚合变量的重新赋值各自回收旧值；
 *   * 嵌套 `Result` 的每一层各有一份独立的字符串。
 */

import std::text;

enum Lookup { Missing(String key), Found(String key, String value) };

/* 构造器实参是拼接结果：临时串构造完就归还，聚合里留的是自己的一份。 */
Lookup find(String key, String value) {
    if (value == "") {
        return Lookup::Missing(key + "!");
    }
    return Lookup::Found(key, key + "=" + value);
}

String describe(Lookup item) {
    String result;
    match (item) {
        Lookup::Missing(key) => { result = "missing:" + key; }
        Lookup::Found(key, value) => { result = "found:" + value; }
    }
    return result;
}

Result<String, String> positive(int64 value, String tag) {
    if (value <= 0) { return Result<String, String>::Err("bad:" + tag); }
    return Result<String, String>::Ok(tag + ":" + std::text::Text::repeat("x", value));
}

/* `?` 取出的字符串载荷在源 Result 释放后仍然有效（又拼了一次并装进新的 Result）。 */
Result<String, String> twice(int64 value) {
    String first = positive(value, "v")?;
    Result<String, String> second = positive(value + 1, first);
    String text = second.unwrap();
    return Result<String, String>::Ok(text + "!");
}

void main() {
    Lookup hit = find("id", "42");
    println("{}", describe(hit));
    Lookup miss = find("id", "");
    println("{}", describe(miss));

    (String, String) pair = ("left", "right");
    println("{}|{}", pair.0, pair.1);
    pair = ("up", "down");
    println("{}|{}", pair.0, pair.1);

    match (twice(2)) {
        Result<String, String>::Ok(text) => { println("ok {}", text); }
        Result<String, String>::Err(error) => { println("err {}", error); }
    }
    match (twice(0)) {
        Result<String, String>::Ok(text) => { println("ok {}", text); }
        Result<String, String>::Err(error) => { println("err {}", error); }
    }
}

// 地址复用时默认构造不能误释放残留拥有地址；new 与运行时数组必须初始化。
struct DefaultOwned {
    int32 kind;
    bool ready;
    float32 scale;
    String text;
    List<String> values;
    String fn() callback;
};
String fn() retained(String mut& text) { return fn() { text }; }
void main() {
    {
        int64 i = 0;
        while (i < 20) {

        String parentCallback="parent callback";
        DefaultOwned local;
        local.kind = 7;
        local.text = "parent";
        local.values.push("owned");
        local.callback = retained(&parentCallback);
        DefaultOwned mut& owned = heap DefaultOwned;
        assert(owned.kind == 0 && !owned.ready && owned.scale == 0.0);
        assert(owned.values.len() == 0);
        owned.text = "child";
        owned.values.push("child value");
        owned.callback = retained(&owned.text);
        assert(owned.callback() == "child");
        assert(local.kind == 7 && local.text == "parent" && local.values[0] == "owned");
        assert(local.callback() == "parent callback");
        owned.drop();
        assert(local.text == "parent" && local.callback() == "parent callback");
        String words[] = new[3];
        words[0] = format("{}", i);
        words[1] = "first";
        words[1] = "second";
        assert(words[0] == format("{}", i) && words[1] == "second");
        words.drop();
        int32 numbers[] = new[3];
        assert(numbers[0] == 0 && numbers[2] == 0);

            i = i + 1;
        }
    }
    println("allocated default ownership OK");
}

/* temporary_ownership.chl —— "转换"和"变长实参"里的临时对象由调用点接管
 *
 *   ./chali samples/temporary_ownership.chl
 *
 * 这两处过去会漏：`(int64)BigDecimal("42.9")` 转换只读句柄，没有别的所有者；
 * 变长实参 `g(a + b, Text::repeat(…))` 的临时值也只是被复制进容器、自己没人收尾。
 * 现在调用点会把当场造出来的大数 / 串落进临时变量，随块一起释放。
 * 泄漏提示走 stderr，check.sh 会单独挡一道（见 expected/*.stderr 的约定）。
 */

BigDecimal scale(BigDecimal value) { return value; }
int64 toInt(BigDecimal value) { return (int64)value; }
int64 countBig(BigDecimal... values) { return len(values); }
int64 countText(String... texts) { return len(texts); }

void main() {
    BigDecimal a = BigDecimal("1.5");
    BigDecimal b = BigDecimal("2.5");

    /* 转换的源是"当场造出来的"：转换前先落地，随块释放。 */
    println("{}", (int64)BigDecimal("42.9"));
    println("{}", (int64)(a * b));
    println("{}", (bool)BigInteger("1"));

    /* 变长实参里的临时串 / 临时大数：容器复制一份，自己那份归调用点。 */
    println("{}", countText("a" + "b", "c" + "d"));
    println("{}", countBig(BigDecimal("1.25"), a * b));

    /* 变量实参是借来的，不该被临时变量多收一次。 */
    println("{}", countBig(a, b));
    println("{}", toInt(scale(BigDecimal("7.9"))));
}

// 函数值、枚举载荷和接口分派跨递归调用保持当前帧的拥有值。
interface FrameReader { String read(); };
struct CallableFrame : FrameReader {
    String label;
    String fn() callback;
    String read() { return self.callback(); }
};
enum CallableValue { Empty, Function(String fn() value), Functions(List<String fn()> values); };

String fn() captured(String mut& text) { return fn() { text }; }
CallableFrame frame(String mut& text) {
    CallableFrame result;
    result.label = text;
    result.callback = captured(&text);
    return result;
}
int64 recurse(int64 depth) {
    String label = format("frame {}", depth);
    CallableFrame local = frame(&label);
    CallableValue value = CallableValue::Function(captured(&label));
    List<String fn()> functions;
    functions.push(local.callback);
    CallableValue listValue = CallableValue::Functions(functions);
    Map<String, CallableFrame> frames;
    frames.put("frame", local);
    CallableFrame mut& allocated = heap CallableFrame;
    allocated.label = label;
    allocated.callback = captured(&allocated.label);
    Any boxed;
    boxed.set(&allocated);
    FrameReader const& reader = boxed.getReference();
    int64 total = depth;
    if (depth > 0) {
        int64 fn(int64) next = recurse;
        total = total + next(depth - 1);
    }
    assert(local.label == label && local.callback() == label);
    assert(functions[0]() == label && frames["frame"].read() == label);
    assert(reader.read() == label);
    match (value) {
        CallableValue::Function(callback) => { assert(callback() == label); }
        _ => { assert(false); }
    }
    match (listValue) {
        CallableValue::Functions(callbacks) => { assert(callbacks[0]() == label); }
        _ => { assert(false); }
    }
    allocated.drop();
    return total;
